// ===== ALWAYS OPEN NEW PAGES AT THE TOP (unless a #section is requested) =====
if ('scrollRestoration' in history) history.scrollRestoration = 'manual';
(function () {
  const toTop = () => {
    if (location.hash && location.hash.length > 1 && document.querySelector(location.hash)) return;
    const html = document.documentElement, prev = html.style.scrollBehavior;
    html.style.scrollBehavior = 'auto';
    window.scrollTo(0, 0);
    html.style.scrollBehavior = prev;
  };
  toTop();
  window.addEventListener('DOMContentLoaded', toTop);
  window.addEventListener('load', () => { toTop(); setTimeout(toTop, 60); });
  window.addEventListener('pageshow', toTop);
})();

