    "cs12_s3": "Night 3",
    "cs12_s4": "Roman ruins",
    "cs12_s5": "Bab Mansour",
    "cs12_s6": "Nights 4–5",
    "cs12_s7": "Desert camp · night 6",
    "cs12_s8": "Night 7",
    "cs12_s9": "Oasis & kasbahs",
    "cs12_s10": "Night 8",
