    "cs6_s2": "Notte 1",
    "cs6_s3": "Città romana",
    "cs6_s4": "Notte 2",
    "cs6_s5": "La Piccola Svizzera",
    "cs6_s6": "Campo · notte 3",
    "cs6_s7": "Canyon stretto",
