    "mk12_card": "12 giorni da Marrakech",
    "mk12_card_h": "Marrakech · Todra · campo a Erg Chebbi · Fes · Volubilis · Rabat · Casablanca",
    "mk12_t1": "12 giorni da Marrakech",
    "mk12_t2": "Città imperiali e Sahara",
    "mk12_eyebrow": "Grand tour privato",
    "mk12_dur": "12 giorni · 11 notti",
    "mk12_dur2": "12 giorni",
    "mk12_o1": "Dodici giorni per conoscere davvero il Marocco: la città rossa di Marrakech, le kasbah del sud, le grandi dune del Sahara, le città imperiali del nord e le capitali atlantiche, con calma e tempo per fermarsi.",
    "mk12_o2": "Inizi con due giorni a Marrakech, con una passeggiata guidata nella medina e la visita al Giardino Majorelle. Poi la strada attraversa l’Alto Atlante fino ad Ait Ben Haddou e Ouarzazate, e prosegue per la valle delle Rose e le gole del Todra fino a Merzouga.",
    "mk12_o3": "Nel Sahara te la prendi con calma: musica gnawa a Khamlia, visita a una famiglia nomade e un’escursione in cammello tra le dune di Erg Chebbi per una notte in un campo tendato, con tramonto e alba sulla sabbia.",
    "mk12_o4": "La seconda parte ti porta a nord attraverso la valle dello Ziz, Midelt e le foreste di cedri di Azrou fino a Fes, poi a Volubilis, Meknes, Rabat e Casablanca, prima di un ultimo giorno libero a Marrakech.",
    "mk12_h1": "Medina di Marrakech e Majorelle",
    "mk12_h2": "Ait Ben Haddou e gole del Todra",
    "mk12_h3": "Musica gnawa a Khamlia",
    "mk12_h4": "Cammello e campo nel deserto",
    "mk12_h5": "Medina di Fes con guida locale",
    "mk12_h6": "Volubilis, Rabat e Casablanca",
    "mk12_d1_t": "Benvenuti a Marrakech",
    "mk12_d1": "Ti accogliamo in aeroporto e ti accompagniamo al tuo hotel o riad. Il resto della giornata è tuo per sistemarti e goderti la prima sera nella Città Rossa.",
    "mk12_d1_n": "Hotel o riad a Marrakech",
    "mk12_d2_t": "Marrakech con guida locale",
    "mk12_d2": "Una guida locale ti aspetta nella medina per una passeggiata nella città antica. Dopo il pranzo nel cuore della medina, visiti il Giardino Majorelle prima di una serata libera a Marrakech.",
    "mk12_d2_n": "Hotel o riad a Marrakech",
    "mk12_d3_t": "Marrakech – Ait Ben Haddou – Ouarzazate",
    "mk12_d3": "Attraversiamo l’Alto Atlante sul passo del Tizi n’Tichka fino alla kasbah di Ait Ben Haddou, poi proseguiamo per Ouarzazate e i suoi studi cinematografici. Notte a Ouarzazate.",
    "mk12_d3_n": "Hotel a Ouarzazate",
    "mk12_d4_t": "Ouarzazate – gole del Todra – Merzouga",
    "mk12_d4": "Attraversiamo la valle delle Rose e ci fermiamo alle gole del Todra per camminare tra le alte pareti. In serata arrivi a Merzouga, ai piedi delle dune di Erg Chebbi.",
    "mk12_d4_n": "Hotel a Merzouga",
    "mk12_d5_t": "Alla scoperta di Merzouga",
    "mk12_d5": "Una giornata intorno al deserto: visiti il villaggio di Khamlia per ascoltare musica gnawa, incontri una famiglia nomade e scopri oasi di palme e i paesaggi di Erg Chebbi.",
    "mk12_d5_n": "Hotel a Merzouga",
    "mk12_d6_t": "Cammello e notte nel deserto",
    "mk12_d6": "Nel pomeriggio entri in cammello tra le dune più alte del Marocco e raggiungi il campo al tramonto. Cena tradizionale marocchina, tamburi berberi attorno al fuoco e una notte sotto un cielo pieno di stelle.",
    "mk12_d6_n": "Campo tendato a Erg Chebbi",
    "mk12_d7_t": "Merzouga – Rissani – valle dello Ziz – Midelt",
    "mk12_d7": "Alba sulle dune e colazione al campo. Saliamo verso nord passando per il mercato di Rissani, Erfoud, i palmeti della valle dello Ziz ed Errachidia fino a Midelt.",
    "mk12_d7_n": "Hotel a Midelt",
    "mk12_d8_t": "Midelt – foresta di cedri di Azrou – Fes",
    "mk12_d8": "Attraversiamo il Medio Atlante, ci fermiamo nella foresta di cedri di Azrou per vedere i macachi, passiamo per Ifrane e arriviamo a Fes.",
    "mk12_d8_n": "Hotel o riad a Fes",
    "mk12_d9_t": "Fes con guida locale",
    "mk12_d9": "Esplori la medina medievale di Fes con una guida locale, comprese le concerie e i laboratori di ceramica. Notte in un riad tradizionale.",
    "mk12_d9_n": "Riad a Fes",
    "mk12_d10_t": "Fes – Volubilis – Meknes – Rabat",
    "mk12_d10": "Visitiamo le rovine romane di Volubilis, pranziamo nella città imperiale di Meknes e proseguiamo per Rabat, la capitale, per la notte.",
    "mk12_d10_n": "Hotel a Rabat",
    "mk12_d11_t": "Rabat – Casablanca – Marrakech",
    "mk12_d11": "Scopri i luoghi storici di Rabat, poi lungo l’Atlantico fino a Casablanca per un pranzo o un drink sull’oceano, prima di rientrare a Marrakech.",
    "mk12_d11_n": "Hotel o riad a Marrakech",
    "mk12_d12_t": "Giornata libera e partenza",
    "mk12_d12": "Tempo per gli ultimi acquisti nei souk e per fare le valigie, poi ti accompagniamo in aeroporto per il volo di ritorno.",
    "mk12_i1": "Trasferimenti da e per l’aeroporto di Marrakech",
    "mk12_i2": "Veicolo privato moderno con A/C, carburante incluso",
    "mk12_i3": "Autista-guida esperto che parla inglese e spagnolo",
    "mk12_i4": "Escursione in cammello (uno a persona) e tramonto",
    "mk12_i5": "10 notti in camera privata in hotel o riad",
    "mk12_i6": "1 notte in campo tendato, nel tipo di tenda che preferisci",
    "mk12_i7": "Trasferimento facoltativo in 4×4 al campo al posto dei cammelli",
