function setLanguage(lang) {
  if (!translations[lang]) lang = 'en';
  const dict = translations[lang];
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    if (dict[key]) el.textContent = dict[key];
  });
  document.querySelectorAll('[data-i18n-ph]').forEach(el => {
    const key = el.getAttribute('data-i18n-ph');
    if (dict[key]) el.placeholder = dict[key];
  });
  document.documentElement.lang = lang;
  document.querySelectorAll('.lang-menu button').forEach(b => {
    const on = b.dataset.lang === lang;
    b.classList.toggle('active', on);
    if (on) document.getElementById('langFlag').innerHTML = b.querySelector('.flag').innerHTML;
  });
  document.getElementById('langCode').textContent = lang.toUpperCase();
  try { localStorage.setItem('mat_lang', lang); } catch (e) {}
  const tbt = document.querySelector('.tb-tour b'), h1 = document.querySelector('.c-title');
  if (tbt && h1) tbt.textContent = [...h1.querySelectorAll('.c-line-in')].map(s => s.textContent.trim()).join(' ');
  try { document.dispatchEvent(new CustomEvent('langchange', { detail: lang })); } catch (e) {}
}

// language dropdown
const langDD = document.getElementById('langDD');
const langBtn = document.getElementById('langBtn');
langBtn.addEventListener('click', e => {
  e.stopPropagation();
  const open = langDD.classList.toggle('open');
  langBtn.setAttribute('aria-expanded', open);
});
document.querySelectorAll('.lang-menu button').forEach(btn =>
  btn.addEventListener('click', () => {
    setLanguage(btn.dataset.lang);
    langDD.classList.remove('open');
    langBtn.setAttribute('aria-expanded', false);
  }));
document.addEventListener('click', e => {
  if (!langDD.contains(e.target)) langDD.classList.remove('open');
});
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') langDD.classList.remove('open');
});

let savedLang = 'en';
try { savedLang = localStorage.getItem('mat_lang') || 'en'; } catch (e) {}
setLanguage(savedLang);

