// ===== REVEAL ANIMATION =====
const observer = new IntersectionObserver(entries => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('show');
      observer.unobserve(entry.target);
    }
  });
}, { threshold: 0.15 });
document.querySelectorAll('.reveal, .draw-line').forEach(el => observer.observe(el));


// ===== IMAGE BAND PARALLAX =====
const bandBg = document.querySelector('.band-bg');
if (bandBg && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
  let bandTick = false;
  const moveBand = () => {
    const r = bandBg.parentElement.getBoundingClientRect();
    if (r.bottom > 0 && r.top < window.innerHeight) {
      const p = (r.top + r.height / 2 - window.innerHeight / 2) / window.innerHeight;
      bandBg.style.transform = `translate3d(0, ${Math.max(-12, Math.min(12, p * -12))}%, 0)`;
    }
    bandTick = false;
  };
  window.addEventListener('scroll', () => {
    if (!bandTick) { requestAnimationFrame(moveBand); bandTick = true; }
  }, { passive: true });
  moveBand();
}



// ===== TRIP FINDER =====
(function () {
  const finder = document.getElementById('finder');
  const input = document.getElementById('finderInput');
  const results = document.getElementById('finderResults');
  const empty = document.getElementById('finderEmpty');
  if (!finder) return;
  const norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  // synonyms so visitors find things in their own words / language
  const syn = { day: 'days dias giorni', dia: 'days', giorni: 'days', giorno: 'days', camello: 'camel', cammello: 'camel', cavallo: 'horse', caballo: 'horse', campamento: 'camp', campo: 'camp', fez: 'fes', marrakesh: 'marrakech', desierto: 'desert', deserto: 'desert', atv: 'quad', jeep: '4x4', noche: 'night camp', notte: 'night camp', musica: 'gnawa', compartido: 'shared group', condiviso: 'shared group' };

  function buildIndex() {
    const items = [];
    document.querySelectorAll('.act-card').forEach(card => {
      items.push({ el: card, group: 'act', title: card.querySelector('h3').textContent,
        sub: card.querySelector('.act-dur').textContent, img: card.querySelector('img').getAttribute('src'),
        text: card.textContent + ' merzouga sahara activity ' + card.querySelector('img').alt });
    });
    document.querySelectorAll('.tour-card').forEach(card => {
      const sec = card.closest('section');
      items.push({ el: card, group: 'tour', title: card.querySelector('h3').textContent,
        sub: card.querySelector('.lx-route').textContent.replace(/\s+/g, ' ').trim(),
        img: card.querySelector('img').getAttribute('src'),
        text: card.textContent + ' ' + card.querySelector('img').alt + ' ' + (sec ? sec.querySelector('.section-title').textContent : '') });
    });
    document.querySelectorAll('.dc').forEach(card => {
      items.push({ el: card, group: 'tour', title: card.querySelector('.dc-title').textContent,
        sub: card.querySelector('.dc-from').textContent, img: card.querySelector('img').getAttribute('src'),
        text: card.textContent + ' day trip excursion escursione ' + card.querySelector('img').alt });
    });
    return items;
  }
  let index = [], active = -1, shown = [];

  function render(q) {
    const dict = translations[document.documentElement.lang] || translations.en;
    let terms = norm(q).split(/\s+/).filter(Boolean);
    shown = index.filter(it => {
      const hay = norm(it.text + ' ' + it.title + ' ' + it.sub);
      return terms.every(t => {
        if (/^\d+$/.test(t)) return new RegExp('\\b' + t + '\\b').test(hay);
        const alts = [t].concat((syn[t] || '').split(' ').filter(Boolean));
        return alts.some(a => hay.includes(a));
      });
    });
    if (!terms.length) shown = index.slice(0, 8);
    results.innerHTML = '';
    empty.hidden = shown.length > 0;
    const esc = s => s.replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
    const hi = s => { let out = esc(s); terms.forEach(t => { if (t.length > 1) out = out.replace(new RegExp('(' + t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ')', 'ig'), '<mark>$1</mark>'); }); return out; };
    ['tour', 'act'].forEach(g => {
      const list = shown.filter(i => i.group === g);
      if (!list.length) return;
      const h = document.createElement('div');
      h.className = 'fr-group';
      h.textContent = g === 'act' ? dict.sr_g_act : dict.sr_g_tour;
      results.appendChild(h);
      list.forEach(it => {
        const b = document.createElement('button');
        b.className = 'fr-item';
        b.innerHTML = '<img src="' + it.img + '" alt=""><span><b>' + hi(it.title) + '</b><small>' + hi(it.sub) + '</small></span>';
        b.addEventListener('click', () => go(it));
        results.appendChild(b);
      });
    });
    shown = ['tour', 'act'].flatMap(g => shown.filter(i => i.group === g));
    active = -1;
  }
  function go(it) {
    close();
    it.el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    it.el.classList.remove('flash'); void it.el.offsetWidth; it.el.classList.add('flash');
  }
  function open() {
    index = buildIndex();
    if (!index.length) { location.href = 'index.html#find'; return; }
    finder.classList.add('open'); finder.setAttribute('aria-hidden', 'false');
    input.value = ''; render('');
    document.querySelectorAll('#finderChips button').forEach(b => b.classList.remove('on'));
    setTimeout(() => input.focus(), 60);
  }
  function close() { finder.classList.remove('open'); finder.setAttribute('aria-hidden', 'true'); }

  document.getElementById('searchBtn').addEventListener('click', open);
  document.getElementById('finderBackdrop').addEventListener('click', close);
  document.getElementById('finderClose').addEventListener('click', close);
  input.addEventListener('input', () => render(input.value));
  document.querySelectorAll('#finderChips button').forEach(b => b.addEventListener('click', () => {
    const on = !b.classList.contains('on');
    document.querySelectorAll('#finderChips button').forEach(x => x.classList.remove('on'));
    if (on) b.classList.add('on');
    input.value = on ? b.dataset.q : '';
    render(input.value); input.focus();
  }));
  document.addEventListener('keydown', e => {
    const isOpen = finder.classList.contains('open');
    if (!isOpen && e.key === '/' && !/input|textarea|select/i.test(document.activeElement.tagName)) { e.preventDefault(); open(); return; }
    if (!isOpen) return;
    const items = results.querySelectorAll('.fr-item');
    if (e.key === 'Escape') close();
    else if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      if (!items.length) return;
      active = (active + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length;
      items.forEach((x, i) => x.classList.toggle('active', i === active));
      items[active].scrollIntoView({ block: 'nearest' });
    } else if (e.key === 'Enter' && shown.length) { e.preventDefault(); go(shown[Math.max(0, active)]); }
  });
})();

// ===== 3D TILT ON TOUR CARDS =====
(function () {
  if (!window.matchMedia('(hover: hover) and (pointer: fine)').matches) return;
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  document.querySelectorAll('.lx').forEach(card => {
    card.addEventListener('mousemove', e => {
      const r = card.getBoundingClientRect();
      const x = (e.clientX - r.left) / r.width - .5;
      const y = (e.clientY - r.top) / r.height - .5;
      card.classList.add('tilting');
      card.style.setProperty('--ry', (x * 14).toFixed(2) + 'deg');
      card.style.setProperty('--rx', (-y * 12).toFixed(2) + 'deg');
      card.style.setProperty('--px', (-x * 14).toFixed(1) + 'px');
      card.style.setProperty('--py', (-y * 14).toFixed(1) + 'px');
      card.style.setProperty('--gx', ((x + .5) * 100).toFixed(0) + '%');
      card.style.setProperty('--gy', ((y + .5) * 100).toFixed(0) + '%');
    });
    card.addEventListener('mouseleave', () => {
      card.classList.remove('tilting');
      ['--rx', '--ry', '--px', '--py'].forEach(p => card.style.setProperty(p, p.startsWith('--r') ? '0deg' : '0px'));
    });
  });
})();


