(function () {
  const onHome = () => /(^|\/)(index\.html)?$/.test(location.pathname) || !/\.html$/.test(location.pathname);
  document.querySelectorAll('.logo, .ft-logo, .nav a[data-i18n="nav_home"]').forEach(a => {
    a.addEventListener('click', e => {
      if (!onHome()) return;            // on other pages, go to index.html normally
      e.preventDefault();
      document.querySelectorAll('.nav.open, .burger.open').forEach(x => x.classList.remove('open'));
      window.scrollTo({ top: 0, behavior: 'smooth' });
      if (location.hash) history.replaceState(null, '', location.pathname);
    });
  });
})();

// ===== TOUR CAROUSELS (arrows) =====
(function () {
  document.querySelectorAll('.tg-wrap').forEach(wrap => {
    const track = wrap.querySelector('.tour-grid');
    const prev = wrap.querySelector('.tg-prev');
    const next = wrap.querySelector('.tg-next');
    const step = () => {
      const card = track.querySelector('.tour-card');
      const gap = parseFloat(getComputedStyle(track).columnGap) || 0;
      return card ? card.getBoundingClientRect().width + gap : track.clientWidth;
    };
    const update = () => {
      const max = track.scrollWidth - track.clientWidth - 4;
      prev.disabled = track.scrollLeft <= 4;
      next.disabled = track.scrollLeft >= max;
    };
    prev.addEventListener('click', () => track.scrollBy({ left: -step(), behavior: 'smooth' }));
    next.addEventListener('click', () => track.scrollBy({ left: step(), behavior: 'smooth' }));
    track.addEventListener('scroll', () => requestAnimationFrame(update), { passive: true });
    window.addEventListener('resize', update);
    update();
  });
})();

// ===== FORM SENDING: email (FormSubmit) + big success message =====
(function () {
  const TO = 'contact.moroccoadventurestour@gmail.com';
  const WA = '212678237982';
  const tr = (k, f) => { try { const d = translations[document.documentElement.lang] || translations.en; return d[k] || f; } catch (e) { return f; } };
  const esc = t => String(t).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  function success(form, mode, name) {
    const box = document.createElement('div');
    box.className = 'fs-ok';
    box.setAttribute('role', 'status');
    box.innerHTML =
      '<div class="fs-ic"><svg viewBox="0 0 52 52"><circle cx="26" cy="26" r="24"/><path d="M15 27l7 7 15-16"/></svg></div>' +
      '<h3 class="fs-t">' + esc(tr('fs_t', 'Message sent!')) + '</h3>' +
      '<p class="fs-hi">' + esc(tr('fs_hi', 'Thank you') + (name ? ', ' + name : '')) + '</p>' +
      '<p class="fs-p">' + esc(mode === 'wa' ? tr('fs_p_wa', 'Your message is ready in WhatsApp — just press Send. A copy has also reached our team by email.') : tr('fs_p', 'We have received your request and will reply within 24 hours. Please check your inbox (and your spam folder).')) + '</p>' +
      '<button type="button" class="fs-again">' + esc(tr('fs_again', 'Send another message')) + '</button>';
    form.hidden = true;
    form.parentNode.insertBefore(box, form.nextSibling);
    box.querySelector('.fs-again').addEventListener('click', () => { box.remove(); form.reset(); form.hidden = false; });
    const r = box.getBoundingClientRect();
    if (r.top < 80 || r.top > innerHeight - 200) window.scrollBy({ top: r.top - 140, behavior: 'smooth' });
  }
  window.MAT_send = function (form, mode, subject, lines) {
    const f = form, name = f.name.value.trim(), email = f.email.value.trim();
    const btns = f.querySelectorAll('button[type="submit"], [data-send]');
    if (mode === 'wa') window.open('https://wa.me/' + WA + '?text=' + encodeURIComponent(lines), '_blank', 'noopener');
    btns.forEach(b => { b.disabled = true; });
    const sb = f.querySelector('[data-send="' + mode + '"]');
    const old = sb ? sb.innerHTML : '';
    if (sb && mode === 'mail') sb.innerHTML = '<span>' + esc(tr('fs_sending', 'Sending…')) + '</span>';
    let msgEl = f.querySelector('.fs-err');
    if (msgEl) msgEl.remove();
    fetch('https://formsubmit.co/ajax/' + TO, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
      body: JSON.stringify({ name: name, email: email, _replyto: email, _subject: subject + (mode === 'wa' ? ' (also sent on WhatsApp)' : ''), _template: 'box', _captcha: 'false', message: lines })
    }).then(r => r.json().then(j => ({ ok: r.ok && String(j.success) !== 'false' }))).catch(() => ({ ok: false }))
      .then(res => {
        btns.forEach(b => { b.disabled = false; });
        if (sb) sb.innerHTML = old;
        if (res.ok || mode === 'wa') { success(f, mode, name); return; }
        const e = document.createElement('p');
        e.className = 'fs-err';
        e.innerHTML = esc(tr('fs_err', 'Sorry, the message could not be sent. Please try again or contact us on WhatsApp.')) + ' <a href="https://wa.me/' + WA + '?text=' + encodeURIComponent(lines) + '" target="_blank" rel="noopener">WhatsApp →</a>';
        f.appendChild(e);
      });
  };
})();

