// ===== TOUR DETAIL: gallery slider + section tabs =====
(function () {
  const track = document.getElementById('galTrack');
  if (track) {
    const slides = [...track.querySelectorAll('.td-slide')];
    const cur = document.getElementById('galCur');
    let i = 0;
    const go = n => {
      i = (n + slides.length) % slides.length;
      const s = slides[i];
      track.scrollTo({ left: s.offsetLeft - (track.clientWidth - s.clientWidth) / 2, behavior: 'smooth' });
    };
    const mark = () => {
      const mid = track.scrollLeft + track.clientWidth / 2;
      let best = 0, d = 1e9;
      slides.forEach((s, k) => { const c = Math.abs(s.offsetLeft + s.clientWidth / 2 - mid); if (c < d) { d = c; best = k; } });
      i = best;
      slides.forEach((s, k) => s.classList.toggle('on', k === best));
      if (cur) cur.textContent = String(best + 1).padStart(2, '0');
    };
    document.querySelector('.td-gal-prev').addEventListener('click', () => go(i - 1));
    document.querySelector('.td-gal-next').addEventListener('click', () => go(i + 1));
    track.addEventListener('scroll', () => requestAnimationFrame(mark), { passive: true });
    window.addEventListener('load', mark); mark();
  }
  const tabs = document.querySelectorAll('.td-tabs a');
  if (tabs.length) {
    const secs = [...tabs].map(a => document.querySelector(a.getAttribute('href')));
    window.addEventListener('scroll', () => {
      let on = 0;
      secs.forEach((s, k) => { if (s && s.getBoundingClientRect().top < 220) on = k; });
      tabs.forEach((a, k) => a.classList.toggle('on', k === on));
    }, { passive: true });
  }
})();

